--region import
--- @type GroceryBaseNode
local Base = import("Game.Gachapon.GachaponProgressRewardNode")
--endregion import

--- from: Assets/BundleResources/Prefabs/OverseaStore/OverseaStoreRewardNode.prefab
---@class GroceryProgressRewardNode : GachaponProgressRewardNode
---@field Env                           	GroceryProgressRewardNode               
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field ImgSymbol                     	UnityEngine.RectTransform               
---@field Button                        	UnityEngine.RectTransform               
---@field ImgIcon2                      	UnityEngine.RectTransform               
---@field ImgIcon                       	UnityEngine.RectTransform               
---@field TextProgress                  	UnityEngine.RectTransform               
---@field TextNumber                    	UnityEngine.RectTransform               
---@field ImgBg                         	UnityEngine.RectTransform               
local GroceryProgressRewardNode = Class("GroceryProgressRewardNode", Base)

--region lifecycle
function GroceryProgressRewardNode:Awake()
    Base.Awake(self)
    
    SetButtonAction(self.Button, Bind(self, self.ButtonOnClickHandler))
end
--endregion lifecycle

--region override
function GroceryProgressRewardNode:UpdateNodeDrawState_()
    if self:GetNodeDrawState() == Constants.GetStatus.Can then
        CfUtils.PlayAnimation(self.controller, 'OverseaStoreRewardNode_Available')
    else
        CfUtils.PlayAnimation(self.controller, 'OverseaStoreRewardNode_Default')
    end
    if self:GetNodeDrawState() == Constants.GetStatus.Has then
        CfUtils.SetUISwitchImage(self.ImgBg, 2)
        CfUtils.SetUISwitchText(self.TextNumber, 2)
        CfUtils.SetColorString(self.ImgIcon, '#8c8c8c')
    else
        CfUtils.SetUISwitchImage(self.ImgBg, 1)
        CfUtils.SetUISwitchText(self.TextNumber, 1)
        CfUtils.SetColorString(self.ImgIcon, '#FFFFFF')
    end
end

function GroceryProgressRewardNode:RefreshData(rewardIndex, rewardData)
    Base.RefreshData(self, rewardIndex, rewardData)

    if rewardIndex == 1 then
        CfUtils.SetActive(self.Button, false)
    elseif rewardIndex == 2 then
        CfUtils.SetActive(self.Button, false)
        CfUtils.SetUISwitchImage(self.ImgSymbol, 1)
    elseif rewardIndex == 3 then
        CfUtils.SetActive(self.Button, true)
        CfUtils.SetUISwitchImage(self.ImgSymbol, 2)
    end
end

function GroceryProgressRewardNode:SetNodeDrawState(drawState)
    Base.SetNodeDrawState(self, drawState)

    if self:GetRewardDataIndex() == 1 or self:GetRewardDataIndex() == 2 then
        CfUtils.SetActive(self.Button, drawState == Constants.GetStatus.Not)
    end
end
--endregion override

--region handler
---顶部页签左侧按钮点击回调
function GroceryProgressRewardNode:ButtonOnClickHandler()
    if self:GetRewardDataIndex() == 3 then
        GameUtils.Toast(localize("完成进度即可重置"))
    end
end
--endregion handler

return GroceryProgressRewardNode